supp+=panel('si_robustness',r'\textbf{Normalization, structural sensitivity, and prediction-confidence diagnostics.} \textbf{a}, source-stack study-normalization and augmentation strategies. \textbf{b}, numerical structural-feature perturbation for HIC. \textbf{c}, disagreement versus absolute-error correlation. \textbf{d}, retained-set CV correlation after abstention. These are separate historical diagnostics. Numerical feature perturbations are not physical conformational ensembles, and expert disagreement is not a calibrated primary-model uncertainty interval.','fig:robustness')
supp+=r'\subsection{Regional descriptor screen}'+'\n'
